"use strict";
// Every shape of a relative require, from CommonJS inside an ES package.
exports.viaRequire = () =>
  [
    require("./probe/both").id,
    require("./probe/both/").id,
    require("./probe/dir").id,
    require("./probe/data").id,
    require("./probe").id,
    require("./probe/").id,
    require("./probe/module.mjs").id,
    require("./probe/dir/../both.js").id,
    require("./data").kind,
  ].join(",");
